{
  "drugs": [
    {
      "generic": "furosemide",
      "plain_purpose": "a water pill that helps your body get rid of extra fluid and lowers high blood pressure",
      "common_side_effects": ["peeing a lot", "low potassium", "dizziness", "muscle cramps"],
      "key_warning": "can cause severe fluid and electrolyte loss if the dose is too high"
    },
    {
      "generic": "lisinopril",
      "plain_purpose": "a blood pressure medicine that also helps a weak heart and protects the heart after a heart attack",
      "common_side_effects": ["dry cough", "dizziness", "headache", "low blood pressure"],
      "key_warning": "can harm or kill an unborn baby if taken during pregnancy"
    },
    {
      "generic": "carvedilol",
      "plain_purpose": "a heart medicine that lowers blood pressure, helps a weak heart work better, and protects the heart after a heart attack",
      "common_side_effects": ["dizziness", "feeling tired", "low blood pressure", "slow heartbeat"],
      "key_warning": "do not stop taking it suddenly; doing so can cause chest pain or a heart attack"
    },
    {
      "generic": "clopidogrel",
      "plain_purpose": "a blood thinner that helps prevent heart attacks and strokes",
      "common_side_effects": ["bleeding", "bruising easily", "upset stomach", "nosebleeds"],
      "key_warning": "can cause serious or life‑threatening bleeding"
    },
    {
      "generic": "rosuvastatin",
      "plain_purpose": "a cholesterol‑lowering medicine that helps prevent heart attacks and strokes",
      "common_side_effects": ["headache", "muscle aches", "stomach pain", "feeling tired"],
      "key_warning": "can cause severe muscle damage that may lead to kidney failure"
    },
    {
      "generic": "nitroglycerin",
      "plain_purpose": "a medicine that prevents chest pain (angina) from heart disease",
      "common_side_effects": ["headache", "dizziness", "low blood pressure", "flushing"],
      "key_warning": "can cause a dangerous drop in blood pressure if taken with certain other medicines"
    },
    {
      "generic": "naproxen",
      "plain_purpose": "a pain and inflammation reliever for arthritis, gout, menstrual cramps, and other aches",
      "common_side_effects": ["stomach upset", "heartburn", "dizziness", "headache"],
      "key_warning": "raises the risk of heart attack, stroke, and serious stomach bleeding"
    }
  ]
}
